final projectGuides =
    (jsonDecode(
      r'''{"python-p1":{"steps":["Remember: an expense is one dated payment. AFN amounts are whole numbers. A list holds several payments; a category groups payments such as food or travel. Finish the foundation lessons on lists, loops, and functions first.","Understand: start with [20, 30]. Set total to 0; reading 20 changes it to 20, and reading 30 changes it to 50. An empty list leaves the total at 0. Predict these values before running the code.","Apply: complete total_expenses below. Visit every amount. If any amount is negative, return -1 to reject the whole batch; otherwise add it to total and return total after the loop. Return inside the loop only for an invalid value.","Analyze: move the final return into the loop deliberately. The [20, 30] case then returns 20. Explain why the second payment was skipped, restore the indentation, and rerun all three cases.","Evaluate: the in-app exercise teaches only numeric aggregation and rejection. The complete reference adds date/category validation and atomic JSON replacement. Validate every record before replacing a file so a failed import cannot erase the previous ledger.","Create: use the complete reference to add two food payments and one travel payment, then report a seven-day interval. Its first day is included and the eighth day is excluded. Add an outside-week record and demonstrate that the total stays unchanged. Keep your own prediction, actual output, and explanation in TESTS.md."],"starter":"def total_expenses(amounts):\n    total = 0\n    return total\n\nprint(total_expenses([20, 30]))\nprint(total_expenses([]))\nprint(total_expenses([20, -5]))","solution":"def total_expenses(amounts):\n    total = 0\n    for amount in amounts:\n        if amount < 0:\n            return -1\n        total = total + amount\n    return total\n\nprint(total_expenses([20, 30]))\nprint(total_expenses([]))\nprint(total_expenses([20, -5]))","expected":"50\n0\n-1","file":"expense_ledger.py","commands":"python expense_ledger.py add 2026-09-12 Food 20\npython expense_ledger.py add 2026-09-13 Food 30\npython expense_ledger.py add 2026-09-14 Travel 10\npython expense_ledger.py report 2026-09-12","reference":"\"\"\"Offline household ledger. python expense_ledger.py --help\"\"\"\nimport argparse\nfrom datetime import date, timedelta\nimport json\nimport os\nfrom pathlib import Path\nimport tempfile\n\n\ndef validate(records):\n    if not isinstance(records, list):\n        raise ValueError('Ledger must be a list')\n    clean = []\n    for record in records:\n        if not isinstance(record, dict) or set(record) != {'date', 'category', 'amount'}:\n            raise ValueError('Every expense needs date, category and amount')\n        day, category, amount = record['date'], record['category'], record['amount']\n        if not isinstance(day, str) or date.fromisoformat(day).isoformat() != day:\n            raise ValueError('Use a valid YYYY-MM-DD date')\n        if not isinstance(category, str) or not category.strip():\n            raise ValueError('Category cannot be blank')\n        if type(amount) is not int or amount < 0:\n            raise ValueError('Amount must be a nonnegative integer AFN value')\n        clean.append({'date': day, 'category': category.strip(), 'amount': amount})\n    return clean\n\n\ndef load(path):\n    path = Path(path)\n    return validate(json.loads(path.read_text(encoding='utf-8'))) if path.exists() else []\n\n\ndef save(path, records):\n    \"\"\"Validate before writing; replacement is atomic on the same filesystem.\"\"\"\n    text = json.dumps(validate(records), ensure_ascii=False, indent=2)\n    path = Path(path)\n    temporary = None\n    try:\n        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=path.parent,\n                                         delete=False) as stream:\n            temporary = Path(stream.name)\n            stream.write(text)\n            stream.flush()\n            os.fsync(stream.fileno())\n        os.replace(temporary, path)\n    finally:\n        if temporary is not None and temporary.exists():\n            temporary.unlink()\n\n\ndef weekly(records, start):\n    first = date.fromisoformat(start)\n    if first.isoformat() != start:\n        raise ValueError('Use YYYY-MM-DD for week start')\n    end = first + timedelta(days=7)\n    totals = {}\n    for record in validate(records):\n        if first <= date.fromisoformat(record['date']) < end:\n            category = record['category']\n            totals[category] = totals.get(category, 0) + record['amount']\n    return {'categories': dict(sorted(totals.items())), 'total': sum(totals.values())}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--file', type=Path, default=Path('expenses.json'))\n    commands = parser.add_subparsers(dest='command', required=True)\n    add = commands.add_parser('add')\n    add.add_argument('date'); add.add_argument('category'); add.add_argument('amount', type=int)\n    report = commands.add_parser('report')\n    report.add_argument('start', help='First of seven included days: YYYY-MM-DD')\n    args = parser.parse_args()\n    try:\n        records = load(args.file)\n        if args.command == 'add':\n            save(args.file, records + [{'date': args.date, 'category': args.category, 'amount': args.amount}])\n            print('Saved')\n        else:\n            print(json.dumps(weekly(records, args.start), ensure_ascii=False, indent=2))\n    except (ValueError, OSError) as error:\n        parser.exit(2, f'Error: {error}\\n')\n\n\nif __name__ == '__main__':\n    main()\n"},"python-p2":{"steps":["Remember: one attendance record identifies a student, a date, and whether the student attended. Use 1 for present and 0 for absent. A percentage compares attended sessions with that student's recorded sessions.","Understand: [1, 0, 1, 1] has four sessions and three attendances. Three divided by four, multiplied by 100, is 75 percent. Do not divide by the number of students or by every day on the calendar.","Apply: complete attendance_percent. Count the list length first. Return -1 if the list is empty, meaning no percentage is available. Reject values other than 0 or 1 with -1. Add the remaining values and divide only after the empty case is handled.","Analyze: remove the empty-list guard and run the empty example. Explain the division-by-zero failure. Restore the guard, then try [1, 2] to show why a presence marker must be validated before it enters the total.","Evaluate: the complete CSV program rejects duplicate student/date rows rather than silently counting a session twice. A header-only input produces a header-only report; a student with no records has no report row. This differs from zero percent, which means recorded sessions were all missed.","Create: save a CSV with header student_id,date,present and three fictional records. Run the reference program and inspect the exported UTF-8 report. Add a duplicate row, verify rejection, and confirm that a previously valid report is unchanged. Document the denominator and missing-record limitation."],"starter":"def attendance_percent(sessions):\n    return 0\n\nprint(attendance_percent([1, 0, 1, 1]))\nprint(attendance_percent([0, 0]))\nprint(attendance_percent([]))\nprint(attendance_percent([1, 2]))","solution":"def attendance_percent(sessions):\n    count = len(sessions)\n    if count == 0:\n        return -1\n    attended = 0\n    for present in sessions:\n        if present != 0 and present != 1:\n            return -1\n        attended = attended + present\n    return attended * 100 / count\n\nprint(attendance_percent([1, 0, 1, 1]))\nprint(attendance_percent([0, 0]))\nprint(attendance_percent([]))\nprint(attendance_percent([1, 2]))","expected":"75.0\n0.0\n-1\n-1","file":"attendance.py","commands":"python attendance.py attendance.csv report.csv\n# attendance.csv:\n# student_id,date,present\n# S1,2026-09-12,1\n# S1,2026-09-13,0\n# S2,2026-09-12,1","reference":"\"\"\"Offline attendance CSV analyst. python attendance.py input.csv report.csv\"\"\"\nimport argparse\nimport csv\nfrom datetime import date\nfrom pathlib import Path\nimport re\n\nFIELDS = ['student_id', 'date', 'present']\n\n\ndef read_attendance(path):\n    records, seen = [], set()\n    with Path(path).open(encoding='utf-8-sig', newline='') as stream:\n        reader = csv.DictReader(stream, strict=True)\n        if reader.fieldnames != FIELDS:\n            raise ValueError('Expected header student_id,date,present')\n        for number, row in enumerate(reader, 2):\n            if set(row) != set(FIELDS) or any(value is None for value in row.values()):\n                raise ValueError(f'Row {number}: incorrect column count')\n            student, day, present = (row[key] for key in FIELDS)\n            if not re.fullmatch(r'[A-Za-z0-9_-]{1,32}', student):\n                raise ValueError(f'Row {number}: invalid student ID')\n            try:\n                if date.fromisoformat(day).isoformat() != day:\n                    raise ValueError('Noncanonical date')\n            except ValueError as error:\n                raise ValueError(f'Row {number}: invalid YYYY-MM-DD date') from error\n            if present not in ('0', '1'):\n                raise ValueError(f'Row {number}: present must be 0 or 1')\n            if (student, day) in seen:\n                raise ValueError(f'Row {number}: duplicate student/date')\n            seen.add((student, day))\n            records.append((student, day, int(present)))\n    return records\n\n\ndef summarize(records):\n    \"\"\"Denominator = this student's recorded sessions, not all calendar days.\"\"\"\n    totals = {}\n    for student, _, present in records:\n        attended, sessions = totals.get(student, (0, 0))\n        totals[student] = attended + present, sessions + 1\n    return [(student, attended, sessions, round(100 * attended / sessions, 2))\n            for student, (attended, sessions) in sorted(totals.items())]\n\n\ndef export_report(path, rows):\n    with Path(path).open('w', encoding='utf-8', newline='') as stream:\n        writer = csv.writer(stream)\n        writer.writerow(['student_id', 'attended', 'sessions', 'percent'])\n        writer.writerows(rows)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('input', type=Path)\n    parser.add_argument('output', type=Path)\n    args = parser.parse_args()\n    try:\n        if args.input.resolve() == args.output.resolve():\n            raise ValueError('Output must differ from input')\n        # Parse and validate fully before opening the report for writing.\n        rows = summarize(read_attendance(args.input))\n        export_report(args.output, rows)\n        print(f'{len(rows)} students; header-only report means no recorded sessions.')\n    except (ValueError, OSError, csv.Error) as error:\n        parser.exit(2, f'Error: {error}\\n')\n\n\nif __name__ == '__main__':\n    main()\n"},"python-p3":{"steps":["Remember: stock is the number of available items. A sale reduces stock. An invariant is a rule that must always hold: stock must never become negative, and a sale quantity must be positive.","Understand: with stock 5, selling 2 leaves 3. Selling 6 must fail and leave 5. Separate the decision from storage: first learn a pure function that calculates the next stock without changing any outside value.","Apply: complete stock_after_sale. Reject negative stock, zero or negative quantity, and quantities above available stock by returning -1. For a valid sale return stock minus quantity. Selling exactly the available stock should return 0.","Analyze: replace quantity > stock with quantity >= stock. The exact-stock sale now fails. Explain the difference between these comparisons, fix it, and retain that example as a regression test.","Evaluate: saving stock and recording a sale are one business operation. In the SQLite reference, both statements share a transaction. If recording the sale fails, stock rolls back too. A conditional UPDATE also stops a second connection from overselling stale stock.","Create: run the complete shop reference with a fictional Pen item. Sell two, reopen the program, and inspect the low-stock report and JSON export. Attempt an oversale and verify stock and sales remain unchanged. Extend your design with a restock operation and explain which operations must be atomic."],"starter":"def stock_after_sale(stock, quantity):\n    return stock\n\nprint(stock_after_sale(5, 2))\nprint(stock_after_sale(5, 6))\nprint(stock_after_sale(5, 0))\nprint(stock_after_sale(5, 5))","solution":"def stock_after_sale(stock, quantity):\n    if stock < 0 or quantity <= 0 or quantity > stock:\n        return -1\n    return stock - quantity\n\nprint(stock_after_sale(5, 2))\nprint(stock_after_sale(5, 6))\nprint(stock_after_sale(5, 0))\nprint(stock_after_sale(5, 5))","expected":"3\n-1\n-1\n0","file":"inventory.py","commands":"python inventory.py add Pen 5\npython inventory.py sell Pen 2\npython inventory.py low\npython inventory.py export snapshot.json\npython inventory.py sell Pen 99","reference":"\"\"\"Offline transactional shop. python inventory.py --help\"\"\"\nimport argparse\nimport json\nfrom pathlib import Path\nimport sqlite3\n\n\nclass Inventory:\n    def __init__(self, path):\n        self.db = sqlite3.connect(path)\n        self.db.execute('PRAGMA foreign_keys=ON')\n        with self.db:\n            self.db.execute('CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, stock INTEGER NOT NULL CHECK(stock>=0))')\n            self.db.execute('CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY, sku TEXT NOT NULL REFERENCES items(sku), quantity INTEGER NOT NULL CHECK(quantity>0))')\n\n    def close(self):\n        self.db.close()\n\n    def add(self, sku, stock):\n        if not isinstance(sku, str) or not sku.strip() or type(stock) is not int or stock < 0:\n            raise ValueError('Use a nonblank SKU and nonnegative integer stock')\n        with self.db:\n            self.db.execute('INSERT INTO items VALUES (?, ?)', (sku.strip(), stock))\n\n    def sell(self, sku, quantity):\n        if type(quantity) is not int or quantity <= 0:\n            raise ValueError('Sale quantity must be a positive integer')\n        # A single conditional UPDATE prevents overselling across connections.\n        # The sales INSERT and stock UPDATE commit or roll back together.\n        with self.db:\n            changed = self.db.execute('UPDATE items SET stock=stock-? WHERE sku=? AND stock>=?', (quantity, sku, quantity))\n            if changed.rowcount != 1:\n                raise ValueError('Unknown SKU or insufficient stock')\n            self.db.execute('INSERT INTO sales(sku,quantity) VALUES (?,?)', (sku, quantity))\n\n    def low_stock(self, threshold=3):\n        if type(threshold) is not int or threshold < 0:\n            raise ValueError('Threshold must be a nonnegative integer')\n        return self.db.execute('SELECT sku,stock FROM items WHERE stock<=? ORDER BY sku', (threshold,)).fetchall()\n\n    def snapshot(self):\n        # One read transaction gives a consistent items/sales snapshot.\n        self.db.execute('BEGIN')\n        try:\n            return {'items': [{'sku': sku, 'stock': stock} for sku, stock in self.db.execute('SELECT sku,stock FROM items ORDER BY sku')],\n                    'sales': [{'id': id_, 'sku': sku, 'quantity': qty} for id_, sku, qty in self.db.execute('SELECT id,sku,quantity FROM sales ORDER BY id')]}\n        finally:\n            self.db.rollback()\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--db', type=Path, default=Path('shop.sqlite'))\n    commands = parser.add_subparsers(dest='command', required=True)\n    add = commands.add_parser('add'); add.add_argument('sku'); add.add_argument('stock', type=int)\n    sell = commands.add_parser('sell'); sell.add_argument('sku'); sell.add_argument('quantity', type=int)\n    low = commands.add_parser('low'); low.add_argument('--threshold', type=int, default=3)\n    export = commands.add_parser('export'); export.add_argument('output', type=Path)\n    args = parser.parse_args()\n    store = None\n    try:\n        if args.command == 'export' and args.output.resolve() == args.db.resolve():\n            raise ValueError('Export must not replace the database')\n        store = Inventory(args.db)\n        if args.command == 'add': store.add(args.sku, args.stock)\n        elif args.command == 'sell': store.sell(args.sku, args.quantity)\n        elif args.command == 'low': print(json.dumps(store.low_stock(args.threshold), ensure_ascii=False))\n        else: args.output.write_text(json.dumps(store.snapshot(), ensure_ascii=False, indent=2), encoding='utf-8')\n    except (ValueError, OSError, sqlite3.Error) as error:\n        parser.exit(2, f'Error: {error}\\n')\n    finally:\n        if store is not None: store.close()\n\n\nif __name__ == '__main__':\n    main()\n"}}''',
